<span class="line">            <span class="token punctuation">.</span><span class="token function">ResideInNamespace</span><span class="token punctuation">(</span><span class="token string">&quot;Microsoft.EntityFrameworkCore&quot;</span><span class="token punctuation">)</span></span>
